package workerpool

import (
	"context"
	"sync"
)

// Job represents a unit of work to be processed by the worker pool.
type Job struct {
	ID      int
	Payload interface{}
}

// Result represents the outcome of processing a job.
type Result struct {
	JobID int
	Value interface{}
	Err   error
}

// WorkerPool manages a bounded set of workers that process jobs concurrently.
// It supports context cancellation, ordered results, and error propagation.
type WorkerPool struct {
	jobs    chan Job
	results chan Result
	wg      sync.WaitGroup
	numWorkers int
}

// NewWorkerPool creates a new WorkerPool with the specified number of workers
// and job queue capacity.
func NewWorkerPool(numWorkers, queueSize int) *WorkerPool {
	if numWorkers <= 0 {
		numWorkers = 1
	}
	if queueSize <= 0 {
		queueSize = numWorkers
	}
	return &WorkerPool{
		jobs:       make(chan Job, queueSize),
		results:    make(chan Result, queueSize),
		numWorkers: numWorkers,

